// zigoCStringBytes copies value into a NUL-terminated Go buffer the native
// call may read for its duration.
func zigoCStringBytes(value string) []byte {
	buffer := make([]byte, len(value)+1)
	copy(buffer, value)
	return buffer
}

// zigoStringSliceArgs flattens values into one NUL-separated byte buffer and
// a length per element, both in Go memory and free of Go pointers, so the
// native call borrows them without an allocation per element.
func zigoStringSliceArgs(values []string) (data []byte, lens []uintptr) {
	if len(values) == 0 {
		return nil, nil
	}
	lens = make([]uintptr, len(values))
	total := 0
	for _, value := range values {
		total += len(value) + 1
	}
	data = make([]byte, total)
	offset := 0
	for i, value := range values {
		lens[i] = uintptr(len(value))
		copy(data[offset:], value)
		offset += len(value) + 1
	}
	return data, lens
}

func zigoBytesPtr(data []byte) unsafe.Pointer {
	if len(data) == 0 {
		return nil
	}
	return unsafe.Pointer(&data[0])
}

func zigoUintptrsPtr(lens []uintptr) unsafe.Pointer {
	if len(lens) == 0 {
		return nil
	}
	return unsafe.Pointer(&lens[0])
}

// zigoCallFrame holds one direct call's arguments and the slots its out
// parameters are written to. purego.SyscallN lets its argument slice escape,
// and native code must not be handed an address on a goroutine stack that a
// callback could grow and move, so both live in a pooled frame on the heap.
type zigoCallFrame struct {
	args [8]uintptr
	out  [5]uint64
}

var zigoCallFrames = sync.Pool{New: func() any { return new(zigoCallFrame) }}

// zigoEscapeSink is never written. zigoEscape only has to look as though it
// might store its argument, so that the compiler keeps what a pointer handed
// to native code points at on the heap, as a call through RegisterFunc did.
var zigoEscapeSink struct {
	enabled bool
	p       unsafe.Pointer
}

func zigoEscape(p unsafe.Pointer) {
	if zigoEscapeSink.enabled {
		zigoEscapeSink.p = p
	}
}

